// Minimal debugger: runs a command line under the Win32 debug API and prints a
// symbolized stack for every access violation (first and second chance).
// Usage: minidbg.exe <exe> [args...]
#include <windows.h>
#include <dbghelp.h>
#include <cstdio>
#include <string>
#pragma comment(lib, "dbghelp.lib")

static bool g_sym_init = false;

static void print_stack(HANDLE process, DWORD tid, const EXCEPTION_RECORD& er, bool first)
{
    if (!g_sym_init) {
        SymSetOptions(SYMOPT_LOAD_LINES | SYMOPT_UNDNAME | SYMOPT_DEFERRED_LOADS);
        g_sym_init = SymInitialize(process, nullptr, TRUE) != FALSE;
    } else {
        SymRefreshModuleList(process);
    }
    HANDLE thread = OpenThread(THREAD_ALL_ACCESS, FALSE, tid);
    CONTEXT ctx{};
    ctx.ContextFlags = CONTEXT_FULL;
    GetThreadContext(thread, &ctx);
    fprintf(stderr, "\n=== %s-chance exception 0x%08lX at %p, thread %lu",
            first ? "first" : "second", er.ExceptionCode, er.ExceptionAddress, tid);
    if (er.ExceptionCode == EXCEPTION_ACCESS_VIOLATION && er.NumberParameters >= 2)
        fprintf(stderr, " (%s 0x%llX)", er.ExceptionInformation[0] ? "write" : "read",
                (unsigned long long)er.ExceptionInformation[1]);
    fprintf(stderr, "\nrcx=%llX rdx=%llX r8=%llX\n", ctx.Rcx, ctx.Rdx, ctx.R8);
    STACKFRAME64 frame{};
    frame.AddrPC.Offset = ctx.Rip;    frame.AddrPC.Mode = AddrModeFlat;
    frame.AddrFrame.Offset = ctx.Rbp; frame.AddrFrame.Mode = AddrModeFlat;
    frame.AddrStack.Offset = ctx.Rsp; frame.AddrStack.Mode = AddrModeFlat;
    for (int i = 0; i < 60; ++i) {
        if (!StackWalk64(IMAGE_FILE_MACHINE_AMD64, process, thread, &frame, &ctx, nullptr,
                         SymFunctionTableAccess64, SymGetModuleBase64, nullptr))
            break;
        DWORD64 pc = frame.AddrPC.Offset;
        if (pc == 0) break;
        char buf[sizeof(SYMBOL_INFO) + 1024]{};
        auto* sym = reinterpret_cast<SYMBOL_INFO*>(buf);
        sym->SizeOfStruct = sizeof(SYMBOL_INFO);
        sym->MaxNameLen = 1000;
        DWORD64 disp = 0;
        IMAGEHLP_MODULE64 mod{}; mod.SizeOfStruct = sizeof(mod);
        SymGetModuleInfo64(process, pc, &mod);
        std::string name = SymFromAddr(process, pc, &disp, sym) ? sym->Name : "?";
        IMAGEHLP_LINE64 line{}; line.SizeOfStruct = sizeof(line);
        DWORD ldisp = 0;
        bool has_line = SymGetLineFromAddr64(process, pc, &ldisp, &line) != FALSE;
        fprintf(stderr, "#%02d %s!%s+0x%llX", i, mod.ModuleName, name.c_str(), (unsigned long long)disp);
        if (has_line) fprintf(stderr, "  %s:%lu", line.FileName, line.LineNumber);
        fprintf(stderr, "\n");
    }
    fflush(stderr);
    CloseHandle(thread);
}

int wmain(int argc, wchar_t** argv)
{
    if (argc < 2) { fprintf(stderr, "usage: minidbg <exe> [args]\n"); return 2; }
    std::wstring cmd;
    for (int i = 1; i < argc; ++i) {
        if (i > 1) cmd += L' ';
        cmd += L'"'; cmd += argv[i]; cmd += L'"';
    }
    STARTUPINFOW si{ sizeof(si) };
    PROCESS_INFORMATION pi{};
    if (!CreateProcessW(nullptr, cmd.data(), nullptr, nullptr, FALSE, DEBUG_ONLY_THIS_PROCESS,
                        nullptr, nullptr, &si, &pi)) {
        fprintf(stderr, "CreateProcess failed %lu\n", GetLastError());
        return 3;
    }
    DWORD exit_code = 0;
    for (;;) {
        DEBUG_EVENT ev{};
        if (!WaitForDebugEvent(&ev, INFINITE)) break;
        DWORD status = DBG_CONTINUE;
        switch (ev.dwDebugEventCode) {
        case CREATE_PROCESS_DEBUG_EVENT:
            if (ev.u.CreateProcessInfo.hFile) CloseHandle(ev.u.CreateProcessInfo.hFile);
            break;
        case LOAD_DLL_DEBUG_EVENT:
            if (ev.u.LoadDll.hFile) CloseHandle(ev.u.LoadDll.hFile);
            break;
        case EXCEPTION_DEBUG_EVENT: {
            const auto& er = ev.u.Exception.ExceptionRecord;
            bool first = ev.u.Exception.dwFirstChance != 0;
            if (er.ExceptionCode == EXCEPTION_BREAKPOINT || er.ExceptionCode == 0x4000001F) {
                status = DBG_CONTINUE;
            } else {
                if (er.ExceptionCode == EXCEPTION_ACCESS_VIOLATION || er.ExceptionCode == 0xC0000374 ||
                    er.ExceptionCode == 0xC0000409 || !first)
                    print_stack(pi.hProcess, ev.dwThreadId, er, first);
                status = DBG_EXCEPTION_NOT_HANDLED;
            }
            break;
        }
        case EXIT_PROCESS_DEBUG_EVENT:
            exit_code = ev.u.ExitProcess.dwExitCode;
            ContinueDebugEvent(ev.dwProcessId, ev.dwThreadId, DBG_CONTINUE);
            fprintf(stderr, "\n=== process exited 0x%08lX\n", exit_code);
            return (int)exit_code;
        default: break;
        }
        ContinueDebugEvent(ev.dwProcessId, ev.dwThreadId, status);
    }
    return 4;
}

